import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  Watch,
} from '@stencil/core';
import { DrillDownChangeEvent, NavigationSizes } from '../../../../../../types';

/**
 * @slot default - here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-global-side-navigation-drilldown-item',
  styleUrl: 'global-side-navigation-drilldown-item.scss',
  shadow: { delegatesFocus: true },
})
export class GlobalSideNavigationDrilldownItem implements ComponentInterface {
  /**
   * icon name e.g. 'clock-24'. Use the matching 24px sized icons
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * set item as open
   */
  @Prop({ reflect: true, mutable: true }) open: boolean;

  /**
   * disables the navigation item
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * text for the back button, which is shown when the drilldown is open
   */
  @Prop({ reflect: true }) readonly backButtonText: string = 'Back To Menu';

  /**
   * hidden attribute
   *
   * @internal
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * hidden attribute
   *
   * @internal
   */
  @Prop({ reflect: true }) readonly divider: boolean;

  /**
   @internal
   */
  @Prop({ reflect: true }) readonly iconOnly: boolean = false;

  /**
   * sets a custom accessible text for the icon
   */
  @Prop({ reflect: true, attribute: 'a11y-label-icon' }) readonly a11yLabelIcon: string;

  /**
   * Emitted when the drilldown open state changes
   */
  @Event({ bubbles: true }) groupuiDrilldownChange: EventEmitter<DrillDownChangeEvent>;

  @Element() host: HTMLElement;

  private backButtonRef: HTMLButtonElement;
  private drilldownButtonRef: HTMLButtonElement;
  private drillStackRef: HTMLDivElement;

  @Listen('click')
  handleClick(event: Event): void {
    this.preventEventWhenDisabled(event);
  }

  @Listen('focus')
  handleFocus(event: FocusEvent): void {
    if (this.disabled) {
      this.preventEventWhenDisabled(event);
      this.host.blur();
    }
  }

  @Watch('open')
  watchOpen(open: boolean): void {
    if (open) {
      this.host.setAttribute('aria-expanded', 'true');
    } else {
      this.host.removeAttribute('aria-expanded');
    }
    this.groupuiDrilldownChange.emit({
      open: this.open,
      element: this.host,
    });
  }

  private preventEventWhenDisabled(event: Event): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }

  private getTransitionDuration(): { css: string; ms: number } {
    const duration = getComputedStyle(this.host).getPropertyValue('--transition-duration');
    return {
      css: duration,
      ms: parseFloat(duration) * 1000,
    };
  }

  private handleBackButtonClick = (): void => {
    const { css, ms } = this.getTransitionDuration();
    if (!this.drillStackRef) return;

    this.drillStackRef.style.animationDuration = css;
    this.drillStackRef.classList.remove('slide-in');
    this.drillStackRef.classList.add('slide-out');

    setTimeout(() => {
      this.open = false;
      this.drilldownButtonRef?.focus();
    }, ms);
  };

  private handleDrilldownItemClick = (): void => {
    this.open = true;
    const { ms } = this.getTransitionDuration();
    setTimeout(() => {
      this.backButtonRef?.focus();
    }, ms);
  };

  private getLabelText(): string {
    return this.host.querySelector('[slot="label"]')?.textContent;
  }

  render() {
    if (this.iconOnly) return;
    return (
      <Host>
        <div>
          <button
            tabIndex={this.disabled ? -1 : 0}
            type="button"
            class="drilldown-button"
            disabled={this.disabled}
            onClick={this.handleDrilldownItemClick}
            ref={(el) => (this.drilldownButtonRef = el)}
          >
            {(this.icon || this.iconSource) && (
              <groupui-icon
                name={this.icon}
                src={this.iconSource}
                alt={this.a11yLabelIcon}
                aria-hidden={this.a11yLabelIcon ? null : 'true'}
              />
            )}
            <slot name="label"></slot>
            <groupui-icon id="arrow" name="chevron-right-24" aria-hidden="true" />
          </button>
          {this.open && (
            <div
              ref={(el) => (this.drillStackRef = el)}
              class={{ 'drill-stack': true, 'slide-in': this.open }}
              inert={!this.open || this.disabled}
            >
              <div class="drill-stack-content">
                <button
                  ref={(el) => (this.backButtonRef = el)}
                  class="back-button"
                  onClick={this.handleBackButtonClick}
                  aria-label={this.backButtonText}
                >
                  <span>
                    <groupui-icon name="chevron-left-24" aria-hidden="true" />
                  </span>
                  {this.backButtonText}
                </button>
                <groupui-global-side-navigation-category>
                  <span class="drilldown-stack-label">{this.getLabelText()}</span>
                </groupui-global-side-navigation-category>
                <slot></slot>
              </div>
            </div>
          )}
        </div>
      </Host>
    );
  }
}
